1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"hash/crc32"
8		"io"
9		"os"
10		"sort"
11	)
12	
13	// On-disk checkpoint: the complete committed state at one instant frozen into
14	// a single self-describing file, so reopening can seed memory from it and
15	// replay only the WAL tail written afterwards instead of the whole log.
16	//
17	// Layout, little-endian:
18	//
19	//	magic     uint32   checkpointMagic
20	//	version   uint32   checkpointVersion1
21	//	seq       uint64   highest commit sequence handed out at capture time
22	//	snapshots uint64   cumulative number of snapshots handed out
23	//	offset    uint64   WAL byte offset of the cut: only frames at or past this
24	//	                   offset belong to the post-checkpoint tail replayed on
25	//	                   reopen
26	//	count     uint32   number of terminal key/value entries that follow
27	//	entries   [count]entry
28	//	crc       uint32   IEEE CRC-32 of every preceding byte
29	//
30	// One entry is a flags byte (0 = put, 1 = tombstone), a uint32 key length, a
31	// uint32 value length, the terminal version's commit sequence (uint64), the
32	// key, then the value. A checkpoint describes terminal state only, so every
33	// key appears exactly once: a put carries its final value (empty values
34	// included) and a tombstone carries no value. The per-key sequence is stored
35	// so a tail record replayed afterwards links onto the exact predecessor
36	// version and later compaction still sees globally unique sequence numbers.
37	//
38	// A checkpoint only ever accompanies the WAL it was captured against: the WAL
39	// is never rewritten by a checkpoint, and compaction (the only rewrite)
40	// durably removes any live checkpoint before renaming the replacement log
41	// into place. Thus an offset into the WAL always refers to the log the
42	// checkpoint describes, and a checkpoint found on reopen is trusted up to
43	// its own integrity checks.
44	//
45	// The file is an all-or-nothing artifact: it is built under a temporary name,
46	// forced whole with one fsync, and only then renamed into place (the rename
47	// atomically replaces any previous checkpoint). Missing, truncated,
48	// checksum-bad or unknown-version files are rejected outright; a half
49	// checkpoint is never installed as state.
50	const (
51		checkpointName    = "snapshot.ckpt"
52		checkpointTmpName = "snapshot.ckpt.tmp"
53	
54		checkpointMagic    uint32 = 0x504b4353 // bytes "SCKP"
55		checkpointVersion1 uint32 = 1
56	
57		checkpointHeaderSize      = 4 + 4 + 8 + 8 + 8 + 4
58		checkpointEntrySize       = 1 + 4 + 4 + 8 // flags, keyLen, valLen, seq
59		ckptFlagPut          byte = 0
60		ckptFlagDelete       byte = 1
61	)
62	
63	// checkpointEntry is one terminal key state in a checkpoint.
64	type checkpointEntry struct {
65		key     string
66		value   []byte
67		seq     uint64 // commit sequence of this terminal version
68		present bool
69	}
70	
71	// capturedState is the full content of one checkpoint: the terminal state
72	// plus the watermarks needed to replay only the WAL that follows it.
73	type capturedState struct {
74		entries []checkpointEntry
75		offset  int64
76		seq     uint64
77		snaps   uint64
78	}
79	
80	// errCheckpointRejected marks any validation failure. Such an error is never
81	// surfaced to the caller of Open: a rejected checkpoint is an expected
82	// outcome handled by falling back to WAL-only replay.
83	func errCheckpointRejected(err error) error {
84		return errors.Join(errors.New("snapshot: rejecting checkpoint"), err)
85	}
86	
87	// captureCheckpoint takes a consistent snapshot of committed state. The
88	// caller must hold the store's write lock. Entries are sorted by key for a
89	// canonical encoding; values are copied so later commits cannot mutate the
90	// bytes being serialized. offset is the WAL's current end, the cut point.
91	func captureCheckpoint(v view, offset, seq, snaps uint64) capturedState {
92		entries := make([]checkpointEntry, 0, len(v))
93		for k, n := range v {
94			e := checkpointEntry{key: k, present: n.present, seq: n.seq}
95			if n.present {
96				e.value = cloneBytes(n.value)
97			}
98			entries = append(entries, e)
99		}
100		sort.Slice(entries, func(i, j int) bool { return entries[i].key < entries[j].key })
101		return capturedState{
102			entries: entries,
103			offset:  int64(offset), seq: seq, snaps: snaps,
104		}
105	}
106	
107	// writeCheckpointFile serializes st to name freshly (O_EXCL), forces the
108	// whole file with one fsync and closes it. It never touches the live
109	// checkpoint; the caller renames name over it only once this succeeds.
110	func writeCheckpointFile(dir, name string, st capturedState) (err error) {
111		path := dir + string(os.PathSeparator)
112		f, err := os.OpenFile(path+name, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
113		if err != nil {
114			return err
115		}
116		defer func() {
117			if err != nil {
118				f.Close()
119				os.Remove(path + name)
120			}
121		}()
122	
123		w := bufio.NewWriter(f)
124		head := make([]byte, checkpointHeaderSize)
125		binary.LittleEndian.PutUint32(head[0:4], checkpointMagic)
126		binary.LittleEndian.PutUint32(head[4:8], checkpointVersion1)
127		binary.LittleEndian.PutUint64(head[8:16], st.seq)
128		binary.LittleEndian.PutUint64(head[16:24], st.snaps)
129		binary.LittleEndian.PutUint64(head[24:32], uint64(st.offset))
130		binary.LittleEndian.PutUint32(head[32:36], uint32(len(st.entries)))
131	
132		h := crc32.NewIEEE()
133		if _, err = w.Write(head); err != nil {
134			return err
135		}
136		h.Write(head)
137	
138		ehdr := make([]byte, checkpointEntrySize)
139		for _, e := range st.entries {
140			if len(e.key) > maxRecord || len(e.value) > maxRecord {
141				return errors.New("snapshot: checkpoint entry too large")
142			}
143			if e.present {
144				ehdr[0] = ckptFlagPut
145			} else {
146				ehdr[0] = ckptFlagDelete
147			}
148			binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(e.key)))
149			binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(e.value)))
150			binary.LittleEndian.PutUint64(ehdr[9:17], e.seq)
151			if _, err = w.Write(ehdr); err != nil {
152				return err
153			}
154			h.Write(ehdr)
155			if _, err = io.WriteString(w, e.key); err != nil {
156				return err
157			}
158			h.Write([]byte(e.key))
159			if len(e.value) > 0 {
160				if _, err = w.Write(e.value); err != nil {
161					return err
162				}
163				h.Write(e.value)
164			}
165		}
166	
167		var crcb [crcSize]byte
168		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
169		if _, err = w.Write(crcb[:]); err != nil {
170			return err
171		}
172		if err = w.Flush(); err != nil {
173			return err
174		}
175		if err = f.Sync(); err != nil {
176			return err
177		}
178		return f.Close()
179	}
180	
181	// installCheckpoint builds the complete checkpoint in the temp name and
182	// atomically renames it into place, forcing the directory afterwards. It
183	// touches neither the WAL nor the live writer: a crash at any point leaves
184	// either the previous checkpoint or the new complete one, each describing
185	// the same unchanged WAL. A leftover temp is staging debris and is removed
186	// on the next open.
187	func installCheckpoint(dir string, st capturedState) error {
188		if err := removeStaleCheckpointTmp(dir); err != nil {
189			return err
190		}
191		if err := writeCheckpointFile(dir, checkpointTmpName, st); err != nil {
192			return err
193		}
194		path := dir + string(os.PathSeparator)
195		if err := os.Rename(path+checkpointTmpName, path+checkpointName); err != nil {
196			os.Remove(path + checkpointTmpName)
197			return err
198		}
199		// A crash before this force lands either the old or the new checkpoint
200		// after restart; both are whole and valid against the unchanged WAL.
201		return syncDirectory(dir)
202	}
203	
204	// loadCheckpoint reads and validates the checkpoint in dir.
205	//
206	// A missing file is not an error: ok is false with nil error. Any defect
207	// (truncation, bad checksum, unknown version, malformed field or trailing
208	// bytes) returns ok=false with a non-nil rejection reason, so the caller
209	// falls back to a WAL-only reopen rather than installing partial state.
210	func loadCheckpoint(dir string) (st capturedState, ok bool, err error) {
211		f, rerr := os.Open(dir + string(os.PathSeparator) + checkpointName)
212		if rerr != nil {
213			if errors.Is(rerr, os.ErrNotExist) {
214				return capturedState{}, false, nil
215			}
216			return capturedState{}, false, rerr
217		}
218		defer f.Close()
219	
220		reject := func(err error) (capturedState, bool, error) {
221			return capturedState{}, false, errCheckpointRejected(err)
222		}
223	
224		r := bufio.NewReader(f)
225		h := crc32.NewIEEE()
226	
227		head := make([]byte, checkpointHeaderSize)
228		if _, err := io.ReadFull(r, head); err != nil {
229			return reject(err)
230		}
231		h.Write(head)
232	
233		magic := binary.LittleEndian.Uint32(head[0:4])
234		version := binary.LittleEndian.Uint32(head[4:8])
235		if magic != checkpointMagic || version != checkpointVersion1 {
236			return reject(errors.New("snapshot: unknown checkpoint format"))
237		}
238		st.seq = binary.LittleEndian.Uint64(head[8:16])
239		st.snaps = binary.LittleEndian.Uint64(head[16:24])
240		off := binary.LittleEndian.Uint64(head[24:32])
241		count := binary.LittleEndian.Uint32(head[32:36])
242		if count > maxRecord {
243			return reject(errors.New("snapshot: checkpoint entry count out of range"))
244		}
245		st.offset = int64(off)
246		if uint64(st.offset) != off {
247			return reject(errors.New("snapshot: checkpoint offset out of range"))
248		}
249	
250		st.entries = make([]checkpointEntry, 0, count)
251		ehdr := make([]byte, checkpointEntrySize)
252		seen := make(map[string]bool, count)
253		for i := uint32(0); i < count; i++ {
254			if _, err := io.ReadFull(r, ehdr); err != nil {
255				return reject(err)
256			}
257			h.Write(ehdr)
258			flag := ehdr[0]
259			keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
260			valLen := binary.LittleEndian.Uint32(ehdr[5:9])
261			seq := binary.LittleEndian.Uint64(ehdr[9:17])
262			if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
263				keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
264				(flag == ckptFlagDelete && valLen != 0) {
265				return reject(errors.New("snapshot: malformed checkpoint entry"))
266			}
267			body := make([]byte, int(keyLen)+int(valLen))
268			if _, err := io.ReadFull(r, body); err != nil {
269				return reject(err)
270			}
271			h.Write(body)
272			key := string(body[:keyLen])
273			if seen[key] {
274				return reject(errors.New("snapshot: duplicate key in checkpoint"))
275			}
276			seen[key] = true
277			e := checkpointEntry{key: key, seq: seq, present: flag == ckptFlagPut}
278			if e.present {
279				e.value = cloneBytes(body[keyLen:])
280			}
281			st.entries = append(st.entries, e)
282		}
283	
284		var crcb [crcSize]byte
285		if _, err := io.ReadFull(r, crcb[:]); err != nil {
286			return reject(err)
287		}
288		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
289			return reject(errors.New("snapshot: checkpoint checksum mismatch"))
290		}
291		// Nothing may trail the terminal checksum: trailing bytes mean the file
292		// is not the single artifact a checkpoint is allowed to be.
293		if b, err := r.ReadByte(); err == nil {
294			_ = b
295			return reject(errors.New("snapshot: checkpoint has trailing bytes"))
296		} else if !errors.Is(err, io.EOF) {
297			return reject(err)
298		}
299		return st, true, nil
300	}
301	
302	// removeStaleCheckpointTmp deletes a half-built checkpoint temp left by a
303	// crash mid-checkpoint. Its absence is not an error.
304	func removeStaleCheckpointTmp(dir string) error {
305		err := os.Remove(dir + string(os.PathSeparator) + checkpointTmpName)
306		if err != nil && !errors.Is(err, os.ErrNotExist) {
307			return err
308		}
309		return nil
310	}
311	
312	// removeRejectedCheckpoint discards a checkpoint that failed validation and
313	// forces the directory, so a rejected artifact never lingers or occupies
314	// space. The WAL alone remains a complete source of truth.
315	func removeRejectedCheckpoint(dir string) {
316		if err := os.Remove(dir + string(os.PathSeparator) + checkpointName); err != nil {
317			return
318		}
319		_ = syncDirectory(dir)
320	}
321	
322	// retireCheckpoint durably withdraws a live checkpoint before the WAL is
323	// replaced. Compaction is the only operation that rewrites wal.log, and a
324	// checkpoint's cut offset is meaningful only against the exact log it was
325	// captured against, so the unlink (and its directory force) must be durable
326	// before the replacement log is renamed into place: after a crash at any
327	// instant, a checkpoint can never be found paired with a different WAL. Its
328	// absence is normal and not an error.
329	func retireCheckpoint(dir string) error {
330		path := dir + string(os.PathSeparator) + checkpointName
331		if _, err := os.Stat(path); err != nil {
332			if errors.Is(err, os.ErrNotExist) {
333				return nil
334			}
335			return err
336		}
337		if err := os.Remove(path); err != nil {
338			return err
339		}
340		return syncDirectory(dir)
341	}
