1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"fmt"
10		"io/fs"
11		"os"
12		"sort"
13		"sync"
14		"sync/atomic"
15	)
16	
17	// node is one immutable version in a key's history. Versions form a linked
18	// list from newest to oldest; a snapshot pins the head current when it was
19	// acquired, so overwritten and deleted values stay readable through every
20	// view that references them. seq is the version's commit number, unique and
21	// strictly increasing along each key's chain; it orders versions across the
22	// independent chains that meet again during a pinning compaction.
23	type node struct {
24		value   []byte
25		present bool   // false marks a delete; a present nil/empty value is still a hit
26		seq     uint64 // commit order, 1-based
27		older   *node
28	}
29	
30	// view is an immutable map of keys to their newest version. Updates produce a
31	// fresh map; the current view and every snapshot simply point at one. Views
32	// are never mutated after publication, so reading them needs no lock. The
33	// maps share version chains with their successor views.
34	type view map[string]*node
35	
36	// Store is an open key-value store backed by a directory on disk.
37	type Store struct {
38		mu sync.Mutex // serializes writers and guards the fields below
39	
40		dir       string
41		wal       *walWriter
42		current   atomic.Pointer[view] // latest committed view; lock-free for readers
43		snapshots atomic.Uint64        // cumulative number of snapshots handed out
44		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
45	
46		// Open cursors pin their fixed view's versions against compaction. The
47		// set is read by Compact (which holds mu) and mutated at cursor
48		// open/close, using cursorMu; reads never take either lock.
49		cursorMu sync.Mutex
50		cursors  map[*Cursor]struct{}
51	
52		// Group-commit queue. Batches that arrive while another commit is
53		// forcing the log line up here; one leader drains the queue, encodes the
54		// waiting batches and shares a single flush plus fsync across them.
55		// queueMu only ever guards this queue and committer; it is never held
56		// across disk I/O, so readers and enqueuers never wait on a sync.
57		queueMu   sync.Mutex
58		queue     []*pendingBatch
59		committer bool
60	
61		// Test hook, nil outside tests. leaderHook runs once after a batch has
62		// become leader, before its first queue drain, and lets tests hold a
63		// leader until a known number of batches have coalesced.
64		leaderHook func()
65	
66		closed atomic.Bool
67	}
68	
69	// Snapshot is a stable read-only view of a store captured at one instant. It
70	// owns no store resources of its own and stays usable after the store has
71	// been closed; a cursor opened from it does register with the store while it
72	// pins versions.
73	type Snapshot struct {
74		v     atomic.Pointer[view] // nil once the snapshot is closed
75		store *Store               // back-reference for cursor pin accounting
76	}
77	
78	// Open opens or creates a persistent store in dir. A path that names a
79	// regular file rather than a directory returns an error wrapping
80	// fs.ErrInvalid.
81	func Open(dir string) (*Store, error) {
82		info, err := os.Stat(dir)
83		if err == nil {
84			if !info.IsDir() {
85				return nil, errNotDir
86			}
87		} else {
88			if !errors.Is(err, fs.ErrNotExist) {
89				return nil, err
90			}
91			if err := os.MkdirAll(dir, 0o700); err != nil {
92				return nil, err
93			}
94		}
95	
96		// A replacement log from a compaction killed before its rename can never
97		// be complete state of record; the old wal.log is. Drop the stale file.
98		// Likewise, a checkpoint temp from a kill mid-checkpoint is staging
99		// debris: only the finished snapshot.ckpt is ever read.
100		if err := removeStaleCompact(dir); err != nil {
101			return nil, err
102		}
103		if err := removeStaleCheckpointTmp(dir); err != nil {
104			return nil, err
105		}
106	
107		latest := make(view)
108		var replaySeq uint64
109		var snapshotCount uint64
110		var validSize int64
111	
112		// apply installs one replayed record into the latest view. Legacy
113		// records (written before sequence numbers existed) carry no seq; replay
114		// order is commit order, so number them sequentially.
115		apply := func(op byte, key string, value []byte, seq uint64) {
116			if seq == 0 {
117				replaySeq++
118				seq = replaySeq
119			} else if seq > replaySeq {
120				replaySeq = seq
121			}
122			switch op {
123			case opPut, opPutSeq:
124				latest[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest[key]}
125			case opDelete, opDeleteSeq:
126				latest[key] = &node{present: false, seq: seq, older: latest[key]}
127			}
128		}
129	
130		// Fast reopen: install a checkpoint's terminal state and replay only the
131		// WAL written after it. A checkpoint is accepted only as a whole; any
132		// defect (missing, truncated, checksum, version, implausible cut) rejects
133		// it wholesale and recovery falls back to a from-scratch WAL replay, the
134		// same path a directory that never had a checkpoint takes.
135		cp, cpOK, cpErr := loadCheckpoint(dir)
136		if cpErr != nil {
137			// Discard the rejected artifact so it neither lingers nor pairs with
138			// a future log; the WAL alone is a complete source of truth.
139			removeRejectedCheckpoint(dir)
140			cpOK = false
141		}
142		if cpOK {
143			walLen, sizeErr := walFileSize(dir)
144			if sizeErr != nil {
145				return nil, sizeErr
146			}
147			// The cut must lie inside this exact WAL at a frame boundary (the
148			// writer's end-of-log position at capture time). A cut past the end
149			// means the pairing is wrong; refuse rather than punch a hole in the
150			// log or skip records.
151			if cp.offset < 0 || cp.offset > walLen {
152				removeRejectedCheckpoint(dir)
153				cpOK = false
154			}
155		}
156		if cpOK {
157			for _, e := range cp.entries {
158				latest[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
159			}
160			replaySeq = cp.seq
161			validSize, snapshotCount, err = replayWALTail(dir, cp.offset, cp.snaps, apply)
162			if err != nil {
163				return nil, err
164			}
165		} else {
166			validSize, snapshotCount, err = replayWAL(dir, apply)
167			if err != nil {
168				return nil, err
169			}
170		}
171	
172		wal, err := openWALWriter(dir, validSize)
173		if err != nil {
174			return nil, err
175		}
176	
177		s := &Store{dir: dir, wal: wal, cursors: make(map[*Cursor]struct{}), nextSeq: replaySeq}
178		s.snapshots.Store(snapshotCount)
179		s.current.Store(&latest)
180		return s, nil
181	}
182	
183	// Put stores value under key. An empty key returns an error wrapping
184	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
185	// key reports a hit. The store does not keep a reference to value.
186	func (s *Store) Put(key string, value []byte) error {
187		s.mu.Lock()
188		defer s.mu.Unlock()
189		if s.closed.Load() {
190			return errStoreClosed
191		}
192		if key == "" {
193			return errEmptyKey
194		}
195		seq := s.nextSeq + 1
196		if err := s.wal.appendPut(key, value, seq); err != nil {
197			return err
198		}
199		s.nextSeq = seq
200		next := s.deriveView()
201		next[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: (*s.current.Load())[key]}
202		s.current.Store(&next)
203		return nil
204	}
205	
206	type pendingBatch struct {
207		ops  []BatchOp
208		done chan error // buffered(1); the leader delivers the commit result
209	}
210	
211	// commitPlan is one queued batch resolved against the cumulative state built
212	// up across its whole sync group.
213	type commitPlan struct {
214		view view // cumulative view after this batch; nil when it committed nothing
215	}
216	
217	// BatchOp is one change in a batch committed with CommitBatch. Delete false
218	// stores Value under Key (a nil or empty Value is still a hit); Delete true
219	// removes Key.
220	type BatchOp struct {
221		Key    string
222		Value  []byte
223		Delete bool
224	}
225	
226	// CommitBatch applies a group of writes and deletes as one atomic commit:
227	// the whole batch becomes visible together or not at all, and snapshots and
228	// cursors fixed at any instant see either the state before the batch or the
229	// state after it, never an in-between mixture. Changes are applied in list
230	// order; a later change to the same key overrides an earlier one within the
231	// batch. Concurrent batches take effect in commit (enqueue) order, and a
232	// later committed batch's same-key change overrides an earlier one's.
233	//
234	// Batches committed concurrently share the disk sync: one leader drains the
235	// queue, encodes every waiting batch as its own recoverable framed commit
236	// and forces them all with one flush plus fsync, so N batches arriving
237	// together cost one sync while each stays whole on recovery; a batch that
238	// arrives while a sync is in flight rides the next one. Reads take none of
239	// these locks and are never blocked by the sync.
240	//
241	// If any change has an empty key the whole batch is rejected before it is
242	// queued or committed: an error wrapping fs.ErrInvalid is returned, no frame
243	// is written and the store's state is unchanged. A delete of a key that is
244	// absent or already deleted commits nothing, exactly like Delete; a batch
245	// containing only such no-ops (or an empty slice) commits nothing and
246	// returns nil. CommitBatch on a closed store returns an error wrapping
247	// fs.ErrClosed.
248	//
249	// Each batch is forced to stable storage before its call returns and is
250	// published as one new view; a process killed mid-commit therefore reopens
251	// with the entire batch present or entirely absent. The store does not keep
252	// references to the op Value slices after return.
253	func (s *Store) CommitBatch(ops []BatchOp) error {
254		if s.closed.Load() {
255			return errStoreClosed
256		}
257		if err := validateBatchOps(ops); err != nil {
258			return err
259		}
260	
261		me := &pendingBatch{ops: ops, done: make(chan error, 1)}
262	
263		// Enqueue. queueMu guards only the queue and the leader flag and is
264		// never held across disk I/O, so followers can join a group while the
265		// leader is syncing and readers never wait.
266		s.queueMu.Lock()
267		if s.closed.Load() {
268			s.queueMu.Unlock()
269			return errStoreClosed
270		}
271		s.queue = append(s.queue, me)
272		if s.committer {
273			s.queueMu.Unlock()
274			return <-me.done // the running leader will drain this batch
275		}
276		s.committer = true
277		s.queueMu.Unlock()
278	
279		// Test-only rendezvous: invoked once by the elected leader before its
280		// first queue drain. Production leaves it nil.
281		if s.leaderHook != nil {
282			s.leaderHook()
283		}
284	
285		// Leadership: drain groups until the queue is empty. Each group takes
286		// s.mu while it forces the log, which serializes it with Put, Delete,
287		// Snapshot, Compact and Close, so a group never straddles a log swap.
288		for {
289			s.queueMu.Lock()
290			// Resign and re-check the queue under one critical section, so a
291			// batch enqueuing in this instant either observes the still-active
292			// leader or becomes the next one; no batch can be left queued with
293			// no leader to drain it.
294			if len(s.queue) == 0 {
295				s.committer = false
296				s.queueMu.Unlock()
297				break
298			}
299			group := s.queue
300			s.queue = nil
301			s.queueMu.Unlock()
302			for p, err := range s.commitGroup(group) {
303				group[p].done <- err
304			}
305		}
306	
307		return <-me.done
308	}
309	
310	// validateBatchOps checks argument-only invariants before a batch is queued.
311	// Empty keys map to fs.ErrInvalid, exactly as for Put and Delete.
312	func validateBatchOps(ops []BatchOp) error {
313		for i := range ops {
314			if ops[i].Key == "" {
315				return errEmptyKey
316			}
317		}
318		for i := range ops {
319			if len(ops[i].Key) > maxRecord || (!ops[i].Delete && seqSize+len(ops[i].Value) > maxRecord) {
320				return fmt.Errorf("snapshot: record too large")
321			}
322		}
323		return nil
324	}
325	
326	// commitGroup encodes and forces every queued batch with one flush and one
327	// sync, then publishes one view per effective batch in queue (commit) order.
328	// It returns one result per batch. An encoding or sync failure fails the
329	// whole group: nothing it contained is published or sequenced. The single
330	// committer calls this; s.mu is taken for the entire force, exactly as the
331	// single-key commit path does.
332	func (s *Store) commitGroup(group []*pendingBatch) []error {
333		results := make([]error, len(group))
334	
335		s.mu.Lock()
336		defer s.mu.Unlock()
337		if s.closed.Load() || s.wal == nil {
338			// Close ran between the drain and the lock; nothing can commit.
339			for i := range results {
340				results[i] = errStoreClosed
341			}
342			return results
343		}
344	
345		// Remember where the group starts so any failure can rewind the log:
346		// unacknowledged frames must not linger at EOF and reappear under a
347		// later commit or after a reopen. Nothing is buffered here (the previous
348		// group always flushed), so EOF is the exact offset.
349		groupStart, posErr := s.wal.position()
350		if posErr != nil {
351			for i := range results {
352				results[i] = posErr
353			}
354			return results
355		}
356		rollback := func(cause error) []error {
357			if err := s.wal.truncateTo(groupStart); err != nil {
358				cause = errors.Join(cause, err)
359			}
360			for i := range results {
361				results[i] = cause
362			}
363			return results
364		}
365	
366		next := *s.current.Load()
367		seq := s.nextSeq
368		plans := make([]commitPlan, 0, len(group))
369		encodedAny := false
370	
371		for _, p := range group {
372			// Each batch gets its own cumulative, immutable map, so the view it
373			// publishes is a valid point-in-time state independent of later
374			// batches in the group.
375			view := make(view, len(next)+len(p.ops))
376			for k, v := range next {
377				view[k] = v
378			}
379			var changes []batchChange
380			for i := range p.ops {
381				op := &p.ops[i]
382				head := view[op.Key]
383				if op.Delete {
384					if head == nil || !head.present {
385						continue // idempotent no-op, matching the single Delete
386					}
387					seq++
388					changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
389					view[op.Key] = &node{present: false, seq: seq, older: head}
390				} else {
391					seq++
392					value := cloneBytes(op.Value)
393					changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
394					view[op.Key] = &node{value: value, present: true, seq: seq, older: head}
395				}
396			}
397			if len(changes) > 0 {
398				if err := s.wal.encodeBatch(changes); err != nil {
399					return rollback(err)
400				}
401				encodedAny = true
402			}
403			plans = append(plans, commitPlan{view: ternaryView(len(changes) > 0, view)})
404			next = view
405		}
406	
407		if encodedAny {
408			// One flush, one fsync for the whole group. Return means every
409			// encoded batch in it is durable as a self-contained framed commit.
410			if err := s.wal.flushSync(); err != nil {
411				return rollback(err)
412			}
413		}
414	
415		s.nextSeq = seq
416		for _, plan := range plans {
417			if plan.view != nil {
418				s.current.Store(&plan.view)
419			}
420		}
421		return results
422	}
423	
424	// ternaryView returns v when ok, nil otherwise.
425	func ternaryView(ok bool, v view) view {
426		if ok {
427			return v
428		}
429		return nil
430	}
431	
432	// Get returns the latest committed value for key. Empty keys, keys never
433	// written and deleted keys are all misses: ok is false and err is nil. The
434	// returned bytes are owned by the caller.
435	func (s *Store) Get(key string) ([]byte, bool, error) {
436		if s.closed.Load() {
437			return nil, false, errStoreClosed
438		}
439		if key == "" {
440			return nil, false, nil
441		}
442		val, ok := lookup(*s.current.Load(), key)
443		return val, ok, nil
444	}
445	
446	// Delete removes key. Deleting an empty key returns an error wrapping
447	// fs.ErrInvalid; deleting a key that was never written or is already deleted
448	// is not an error and commits nothing.
449	func (s *Store) Delete(key string) error {
450		s.mu.Lock()
451		defer s.mu.Unlock()
452		if s.closed.Load() {
453			return errStoreClosed
454		}
455		if key == "" {
456			return errEmptyKey
457		}
458		cur := *s.current.Load()
459		if n := cur[key]; n == nil || !n.present {
460			return nil // nothing live to delete: idempotent no-op
461		}
462		seq := s.nextSeq + 1
463		if err := s.wal.appendDelete(key, seq); err != nil {
464			return err
465		}
466		s.nextSeq = seq
467		next := s.deriveView()
468		next[key] = &node{present: false, seq: seq, older: cur[key]}
469		s.current.Store(&next)
470		return nil
471	}
472	
473	// deriveView returns a shallow, mutable copy of the current view. Callers
474	// must hold s.mu and publish the result through s.current before unlocking.
475	func (s *Store) deriveView() view {
476		cur := *s.current.Load()
477		next := make(view, len(cur)+1)
478		for k, v := range cur {
479			next[k] = v
480		}
481		return next
482	}
483	
484	// Compact reclaims history: values that were overwritten or deleted and are
485	// not needed by any open snapshot or cursor are dropped from memory and the
486	// write-ahead log is atomically rewritten, so the directory occupies less
487	// space than before whenever reclaimable history existed.
488	//
489	// Every open snapshot keeps its exact fixed view: its values are untouched
490	// and reads before and after compaction return byte-identical results. Every
491	// open cursor likewise keeps paging through its exact fixed sequence, and
492	// the one version per key its view shows stays in the rewritten log until
493	// the cursor closes; the compaction after that drops it and shrinks the
494	// directory further. A process killed at any point during compaction reopens
495	// in a complete commit state, with every successful write, deletion and the
496	// cumulative snapshot count intact; no intermediate file requires a second
497	// compaction to repair.
498	//
499	// Compact takes no arguments, may be called at any time and serializes with
500	// writes, deletes, snapshots, cursor opens, closing and other compactions;
501	// concurrent or repeated calls queue and all return nil. Compacting a closed
502	// store returns an error wrapping fs.ErrClosed.
503	func (s *Store) Compact() error {
504		s.mu.Lock()
505		defer s.mu.Unlock()
506		if s.closed.Load() {
507			return errStoreClosed
508		}
509	
510		cur := *s.current.Load()
511	
512		// Pinned versions, keyed by commit sequence (globally unique). The
513		// current head of every live key in the latest view is retained; each
514		// open cursor additionally pins the single head version its fixed view
515		// shows for every present key in its range. A deleted key's tombstone is
516		// retained only when a cursor still reads an older value under it, so
517		// replay links that value as the tombstone's predecessor; otherwise the
518		// key is dropped from the rewritten log altogether, as before.
519		pinned := make(map[uint64]*node)
520		keySeqs := make(map[string][]uint64)
521		cursorPins := make(map[string]bool)
522		pin := func(k string, n *node) {
523			if n == nil {
524				return
525			}
526			if _, ok := pinned[n.seq]; !ok {
527				pinned[n.seq] = n
528				keySeqs[k] = append(keySeqs[k], n.seq)
529			}
530		}
531		for _, c := range s.openCursors() {
532			v := *c.v
533			for _, k := range c.keys {
534				cursorPins[k] = true
535				pin(k, v[k]) // exactly the version this cursor pages out
536			}
537		}
538		for k, n := range cur {
539			if n.present || cursorPins[k] {
540				pin(k, n) // live head, or a tombstone shielding a pinned value
541			}
542		}
543	
544		// Emit one oldest-to-newest history per key so replay links the retained
545		// versions into the correct chains. A key deleted with no cursor reading
546		// an older value is absent from keySeqs altogether and drops out of both
547		// the new view and the rewritten log, exactly as in the baseline.
548		keys := make([]string, 0, len(keySeqs))
549		for k := range keySeqs {
550			keys = append(keys, k)
551		}
552		sort.Strings(keys)
553		histories := make([]keyHistory, 0, len(keys))
554		fresh := make(view, len(cur))
555		for _, k := range keys {
556			seqs := keySeqs[k]
557			sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
558			h := keyHistory{key: k, versions: make([]nodeVer, 0, len(seqs))}
559			for _, seq := range seqs {
560				n := pinned[seq]
561				h.versions = append(h.versions, nodeVer{
562					seq: seq, present: n.present, value: n.value,
563				})
564			}
565			histories = append(histories, h)
566	
567			// The new current view gets single-node heads: history nobody pins
568			// becomes unreachable from memory here, while open snapshots and
569			// cursors keep their own views and nodes alive.
570			head := pinned[seqs[len(seqs)-1]]
571			if head.present {
572				fresh[k] = &node{value: head.value, present: true, seq: head.seq}
573			}
574		}
575	
576		// The rewrite is crash-atomic and split into three phases so the live
577		// writer never holds the old wal.log open while it is being replaced:
578		//
579		//  1. build and sync the complete replacement in the temp name (the old
580		//     log and writer are untouched until this succeeds);
581		//  2. close the live writer so no descriptor occupies wal.log (renaming
582		//     over a still-open file is refused by some native filesystems);
583		//  3. atomically rename the temp over wal.log, force the directory and
584		//     open a writer on the new log.
585		//
586		// A failure before the rename leaves the old log and the store exactly
587		// as they were, so committing can continue and a later Compact retries.
588		// A non-nil next writer after install means the rename landed even if
589		// the final directory sync reported an error; adopt it (the old file is
590		// unlinked), publish the matching view and surface the sync error.
591		if err := buildCompactWAL(s.dir, histories, s.snapshots.Load()); err != nil {
592			return err
593		}
594		// The replacement must not meet the old checkpoint on reopen: its frames
595		// and offsets are a different log from the one the checkpoint cuts.
596		// Retire the checkpoint durably while the old wal.log is still in place;
597		// a crash after this but before the rename simply replays the old log in
598		// full. Failure here happens before anything stateful moved, so drop the
599		// staged temp and leave the store untouched.
600		if err := retireCheckpoint(s.dir); err != nil {
601			removeStaleCompact(s.dir)
602			return err
603		}
604		oldWAL := s.wal
605		if err := oldWAL.close(); err != nil {
606			// The replacement is still staged under the temp name and has not
607			// become state of record; remove it so no repair-only intermediate
608			// file lingers, then reopen a writer on the untouched old log.
609			removeStaleCompact(s.dir)
610			reopened, openErr := openWALWriter(s.dir, -1)
611			if openErr != nil {
612				return err // reopen itself failed; surface the close failure
613			}
614			s.wal = reopened
615			return err
616		}
617		nextWAL, renamed, installErr := installCompactWAL(s.dir)
618		if nextWAL == nil {
619			return installErr
620		}
621		s.wal = nextWAL
622		if renamed {
623			s.current.Store(&fresh)
624		}
625		return installErr
626	}
627	
628	// Checkpoint freezes the store's complete committed state into one
629	// self-describing, checksummed file so the next Open seeds memory from it and
630	// replays only the write-ahead log written afterwards, instead of replaying
631	// the whole log. It changes nothing visible: every committed write and
632	// deletion, the cumulative snapshot count and every open snapshot or cursor
633	// are unaffected, and reads keep hitting memory without touching disk.
634	//
635	// Producing a checkpoint and making it live are two distinct steps:
636	//
637	//  1. the full terminal state is captured under the write lock and a
638	//     complete file is built under a temporary name and forced to stable
639	//     storage;
640	//  2. it is atomically renamed over any previous checkpoint and the
641	//     directory is forced.
642	//
643	// The write-ahead log is never modified, so a kill at any instant leaves
644	// either the previous complete checkpoint (or none) with the same intact
645	// log, or the new complete checkpoint; reopen observes one complete
646	// committed state, never a half-installed checkpoint. Repeated checkpoints
647	// atomically replace the old file, which then occupies no further space.
648	//
649	// Checkpoint serializes with writes, batch commits, snapshots, cursor opens,
650	// compaction and closing (it takes the same write lock), but never with
651	// lock-free reads: Get, scans, snapshot reads and cursor paging proceed while
652	// it runs. A batch stays wholly on one side of the captured cut, and history
653	// pinned by open snapshots or cursors is left untouched. On a closed store
654	// Checkpoint returns an error wrapping fs.ErrClosed.
655	func (s *Store) Checkpoint() error {
656		s.mu.Lock()
657		defer s.mu.Unlock()
658		if s.closed.Load() {
659			return errStoreClosed
660		}
661	
662		offset, err := s.wal.position()
663		if err != nil {
664			return err
665		}
666		st := captureCheckpoint(*s.current.Load(), uint64(offset), s.nextSeq, s.snapshots.Load())
667	
668		// Build, force and publish. The WAL and the live state are not touched on
669		// any failure: a leftover temp is staging debris removed on the next open,
670		// and the previous checkpoint (if any) is still intact under its name.
671		return installCheckpoint(s.dir, st)
672	}
673	
674	// openCursors snapshots the set of currently open cursors. Cursor views and
675	// bounds are immutable after opening, so reading their fields here needs no
676	// per-cursor lock.
677	func (s *Store) openCursors() []*Cursor {
678		s.cursorMu.Lock()
679		defer s.cursorMu.Unlock()
680		cs := make([]*Cursor, 0, len(s.cursors))
681		for c := range s.cursors {
682			cs = append(cs, c)
683		}
684		return cs
685	}
686	
687	// Snapshot acquires a stable view. It never observes writes committed after
688	// it returns, and keeps serving that view regardless of later writes,
689	// deletes or Store.Close, until the Snapshot itself is closed.
690	func (s *Store) Snapshot() (*Snapshot, error) {
691		s.mu.Lock()
692		defer s.mu.Unlock()
693		if s.closed.Load() {
694			return nil, errStoreClosed
695		}
696		count := s.snapshots.Add(1)
697		if err := s.wal.appendMeta(count); err != nil {
698			s.snapshots.Add(^uint64(0))
699			return nil, err
700		}
701		snap := &Snapshot{store: s}
702		snap.v.Store(s.current.Load())
703		return snap, nil
704	}
705	
706	// Get reads key from the snapshot's fixed view. Old values overwritten or
707	// deleted afterwards are still readable; keys created afterwards, empty
708	// keys and keys absent or deleted when the snapshot was taken are misses. A
709	// read from a closed snapshot is also a plain miss, never an error. The
710	// returned bytes are owned by the caller.
711	func (s *Snapshot) Get(key string) ([]byte, bool) {
712		if key == "" {
713			return nil, false
714		}
715		v := s.v.Load()
716		if v == nil {
717			return nil, false // closed snapshot
718		}
719		n := (*v)[key]
720		if n == nil || !n.present {
721			return nil, false
722		}
723		return cloneBytes(n.value), true
724	}
725	
726	// Close releases the snapshot's fixed view. Closing more than once is a
727	// no-op returning nil.
728	func (s *Snapshot) Close() error {
729		s.v.Store(nil)
730		return nil
731	}
732	
733	// Close flushes and closes the store. Data already committed stays complete
734	// and readable after reopening the directory. Snapshots still open keep
735	// serving their fixed views until closed themselves; closing an already
736	// closed store is a no-op returning nil.
737	func (s *Store) Close() error {
738		s.mu.Lock()
739		if !s.closed.CompareAndSwap(false, true) {
740			s.mu.Unlock()
741			return nil
742		}
743		wal := s.wal
744		s.wal = nil
745		s.mu.Unlock()
746	
747		return wal.close()
748	}
749	
750	func lookup(v view, key string) ([]byte, bool) {
751		n := v[key]
752		if n == nil || !n.present {
753			return nil, false
754		}
755		return cloneBytes(n.value), true
756	}
757	
758	func cloneBytes(b []byte) []byte {
759		if b == nil {
760			return nil
761		}
762		c := make([]byte, len(b))
763		copy(c, b)
764		return c
765	}
766

