	// bytes: the chain directory holds one base layer only.
	entries, err := os.ReadDir(filepath.Join(dir, cpDirName))
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 {
		t.Fatalf("chain dir has %d entries, want 1", len(entries))
	}
}

